def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--font', type=Path, required=True)
    parser.add_argument('--bold-font', type=Path, required=True)
    args=parser.parse_args()
    pdfmetrics.registerFont(TTFont('Body', str(args.font)))
    pdfmetrics.registerFont(TTFont('Bold', str(args.bold_font)))
    normal=ParagraphStyle('normal',fontName='Body',fontSize=10.3,leading=14,spaceAfter=9,textColor=colors.HexColor('#202522'))
    title=ParagraphStyle('title',fontName='Bold',fontSize=21,leading=25,spaceAfter=17,textColor=colors.HexColor('#234c38'))
    heading=ParagraphStyle('heading',fontName='Bold',fontSize=12,leading=16,spaceBefore=6,spaceAfter=9)
    small=ParagraphStyle('small',parent=normal,fontSize=9,leading=12,spaceAfter=0)
    story=[]; md=[]
    for number,(name,blocks) in enumerate(pages):
        if number: story.append(PageBreak())
        story.append(Paragraph(escape(name),title));md.extend(['# '+name,''])
        for block in blocks:
            if block[0] in ('p','sub'):
                story.append(Paragraph(escape(block[1].replace('₽', 'руб.')),normal if block[0]=='p' else heading))
                md.extend([('## ' if block[0]=='sub' else '')+block[1],''])
            elif block[0]=='table':
                rows,widths=block[1:]
                values=[[Paragraph(escape(str(cell).replace('₽', 'руб.')),small) for cell in row] for row in rows]
                t=Table(values,colWidths=widths,repeatRows=1,hAlign='LEFT')
                t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#edf2ee')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.6,colors.HexColor('#769780')),('LINEBELOW',(0,1),(-1,-1),.25,colors.HexColor('#c8d2cc')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6)]))
                story.extend([t,Spacer(1,10)])
                md.append('| '+' | '.join(rows[0])+' |');md.append('|'+'---|'*len(rows[0]))
                md.extend('| '+' | '.join(map(str,row))+' |' for row in rows[1:]);md.append('')
            elif block[0]=='image':
                story.append(Image(block[1],width=490,height=166.6));story.append(Spacer(1,8))
                md.extend(['![Первый тестовый фрагмент](../results/db2_s1/svm_trace.png)',''])
            elif block[0]=='diagram':
                story.extend([Diagram(), Spacer(1,8)])
                md.extend(['Электроды → усилитель и АЦП → причинный фильтр → окно 50 мс → 40 признаков → LDA / SVM → проверка команды → связь → контроллер привода → начало движения.', ''])
    def footer(canvas,doc):
        canvas.setFont('Body',8);canvas.setFillColor(colors.HexColor('#606a63'))
        canvas.drawString(52,30,'Уверенный хват · SK Challenge 2026')
        canvas.drawRightString(543,30,str(doc.page))
    out=ROOT/'docs/report.pdf'
    doc=SimpleDocTemplate(str(out),pagesize=(595.28,841.89),rightMargin=52,leftMargin=52,topMargin=43,bottomMargin=48,title='Уверенный хват',author='')
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    (ROOT/'docs/report.md').write_text('\n'.join(md).rstrip()+'\n')
    print(out)

if __name__=='__main__':main()
